Object.assign(window.DYLEAN_DATA.files["Library/Init/Data/Subtype/Basic.lean"],{"text":"/-\nCopyright (c) 2017 Johannes Hölzl. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Johannes Hölzl\n-/\nmodule\n\nprelude\npublic import Init.Ext\n\npublic section\n\nnamespace Subtype\n\nuniverse u\nvariable {α : Sort u} {p q : α → Prop}\n\n@[simp]\nprotected theorem «forall» {q : { a // p a } → Prop} : (∀ x, q x) ↔ ∀ a b, q ⟨a, b⟩ :=\n  ⟨fun h a b ↦ h ⟨a, b⟩, fun h ⟨a, b⟩ ↦ h a b⟩\n\n@[simp]\nprotected theorem «exists» {q : { a // p a } → Prop} :\n    (Exists fun x => q x) ↔ Exists fun a => Exists fun b => q ⟨a, b⟩ :=\n  ⟨fun ⟨⟨a, b⟩, h⟩ ↦ ⟨a, b, h⟩, fun ⟨a, b, h⟩ ↦ ⟨⟨a, b⟩, h⟩⟩\n\nend Subtype\n","refs":[[22,18,22,26,"8a17b44193f2",true],[23,5,23,11,"7bb2e9399922",false],[23,28,23,34,"7bb2e9399922",false],[23,44,23,50,"7bb2e9399922",false]]});
